CREATE TABLE inventory (id BINARY(16) NOT NULL PRIMARY KEY,product_id BINARY(16) NOT NULL,sku VARCHAR(100) NOT NULL,quantity_available INT NOT NULL,quantity_reserved INT NOT NULL,reorder_level INT NOT NULL,updated_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT uk_inventory_product UNIQUE(product_id),CONSTRAINT uk_inventory_sku UNIQUE(sku),CONSTRAINT chk_inventory_nonnegative CHECK(quantity_available>=0 AND quantity_reserved>=0 AND reorder_level>=0));
